<script setup lang="ts">
import { courseImage } from "@/utils/media"
import { courses, useDemoStore, money } from '@/stores/demo'
const store = useDemoStore(); const route = useRoute()
const course = computed(() => courses.find(c => c.id === Number(route.params.id)))
const enrollment = computed(() => store.data.enrollments.find(e => e.courseId === course.value?.id))
const progress = computed(() => course.value && enrollment.value ? Math.round(enrollment.value.completed.length / course.value.lessons.length * 100) : 0)
const reviews = computed(() => store.data.reviews.filter(r => r.courseId === course.value?.id))
const selectedLesson = ref<number | null>(null)
const lessonOpen = computed({ get: () => selectedLesson.value !== null, set: value => { if (!value) selectedLesson.value = null } })
const lesson = computed(() => selectedLesson.value !== null ? course.value?.lessons[selectedLesson.value] : undefined)
watch(() => route.params.id, () => { selectedLesson.value = null })
function complete() {
  if (!enrollment.value || selectedLesson.value === null || !course.value) return
  if (!enrollment.value.completed.includes(selectedLesson.value)) enrollment.value.completed.push(selectedLesson.value)
  const next = course.value.lessons.findIndex((_, i) => !enrollment.value?.completed.includes(i))
  selectedLesson.value = next < 0 ? null : next
}
</script>
<template>
  <PageHeader :title="course?.title ?? 'Kursus tidak ditemukan'" eyebrow="ACADEMY" back="/learn/courses" :description="course ? `With ${course.instructor} · ${course.level}` : ''" />
  <VAlert v-if="!course" type="warning">Kursus tidak ditemukan. Pilih kursus lain dari katalog.</VAlert>
  <VRow v-else><VCol cols="12" md="8"><VCard class="pa-5 mb-5"><ProductArt :icon="course.icon" :image="courseImage(course.id)" :alt="course.title" large /><VCardText class="px-0 pb-0"><h3 class="text-h5 mb-3">Tentang kursus</h3><p class="text-body-1" style="line-height: 1.8">{{ course.description }}</p></VCardText></VCard><VCard title="Daftar pelajaran" class="mb-5"><VList lines="two"><VListItem v-for="(item, index) in course.lessons" :key="item.title" :title="`${String(index + 1).padStart(2, '0')}  ${item.title}`" :subtitle="`${item.minutes} menit · ${enrollment?.completed.includes(index) ? 'Sudah selesai' : enrollment ? 'Baca & kerjakan latihan' : 'Ikuti kursus untuk membuka'}`" :disabled="!enrollment" @click="selectedLesson = index"><template #append><VIcon :icon="enrollment?.completed.includes(index) ? 'ri-checkbox-circle-fill' : enrollment ? 'ri-arrow-right-line' : 'ri-lock-line'" :color="enrollment?.completed.includes(index) ? 'primary' : 'secondary'" /></template></VListItem></VList><VCardText v-if="!enrollment" class="text-caption">Ikuti demo gratis untuk membuka materi dan menyimpan progres belajar.</VCardText></VCard><VCard title="Ulasan peserta"><VCardText><div v-for="review in reviews" :key="review.id" class="review-line"><div class="d-flex justify-space-between"><span class="font-weight-medium">{{ review.author }}</span><VRating :model-value="review.rating" readonly color="warning" density="compact" size="16" /></div><p class="mt-2 text-body-2">{{ review.text }}</p></div><p v-if="!reviews.length" class="text-medium-emphasis">Belum ada ulasan. Bagikan pengalaman Anda setelah mengikuti kursus.</p><VBtn :to="`/learn/ratings?course=${course.id}`" variant="tonal" class="mt-4">Baca & tulis ulasan</VBtn></VCardText></VCard></VCol><VCol cols="12" md="4"><VCard><VCardText class="form-stack"><VChip color="primary" class="align-self-start">{{ enrollment ? 'Sudah diikuti' : course.category }}</VChip><h3 class="text-h4">{{ money(course.price) }}</h3><p class="text-body-2">{{ course.lessons.length }} focused lessons · {{ course.lessons.reduce((sum, l) => sum + l.minutes, 0) }} minutes</p><template v-if="enrollment"><div class="d-flex justify-space-between text-body-2"><span>Progres kursus</span><span>{{ progress }}%</span></div><VProgressLinear :model-value="progress" height="7" rounded color="primary" /><VBtn @click="selectedLesson = course.lessons.findIndex((_, i) => !enrollment?.completed.includes(i)) === -1 ? 0 : course.lessons.findIndex((_, i) => !enrollment?.completed.includes(i))">{{ progress === 100 ? 'Pelajari kembali' : 'Lanjut belajar' }}</VBtn><VBtn :to="`/booking?course=${course.id}`" variant="outlined" prepend-icon="ri-calendar-line">Lihat jadwal private course</VBtn></template><VBtn v-else size="large" @click="store.enroll(course.id)">Ikuti kursus · demo gratis</VBtn><p class="text-caption">Mengikuti demo tidak dikenakan biaya. Materi berupa bacaan dan latihan; progres disimpan di browser Anda.</p></VCardText></VCard></VCol></VRow>
  <VDialog v-model="lessonOpen" max-width="700" scrollable aria-label="Course lesson"><VCard v-if="lesson" :title="lesson.title"><VCardText><p class="text-overline text-primary mb-4">BACA · LATIHAN · SIMPAN PROGRES</p><p class="text-body-1" style="line-height: 1.9">{{ lesson.content }}</p><VAlert variant="tonal" type="info" class="mt-5">Selesaikan latihan sebelum menandai pelajaran selesai. Progres tersimpan otomatis.</VAlert></VCardText><VCardActions class="pa-4"><VBtn @click="selectedLesson = null">Tutup</VBtn><VSpacer /><VBtn variant="flat" @click="complete">Selesai & lanjut belajar</VBtn></VCardActions></VCard></VDialog>
</template>
